int array[1000];
for (int i = 0; i < 1000; i++) {
  //Good spatial locality: access array elements sequentially
  array[i] = i * 2; 
}
for (int i = 0; i < 1000; i++) {
  //Good temporal locality: reuse array[i] multiple times
  int value = array[i];
  // ... perform calculations using value ...
}
